#!/usr/bin/env python3
"""GET-only §11.13.5.K post-merge cross-IMR / set-leverage evidence.

No POST. No set-leverage. No funding. No repo write. No secrets printed.
Uses origin/main canary signer primitives; instrument is hardcoded to the
canonical 310404 binding (local dirty tree is not SSOT).
"""

from __future__ import annotations

import json
import ssl
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

from src.ops.section_11_13_5_live_canary_minimum_exposure_v1.constants_v1 import (
    REQUIRED_CREDENTIAL_CLASS,
    REQUIRED_SECRETREF_URI,
    REUSED_BINDING_ACCOUNT_SCOPE,
    REUSED_BINDING_REST_HOST,
    USER_AGENT_CANARY,
)
from src.ops.section_11_13_5_live_canary_minimum_exposure_v1.live_credential_ephemeral_v1 import (
    build_file_secretref_vault_backend_v1,
    release_live_canary_ephemeral_material_v1,
    resolve_and_load_live_canary_secretref_ephemeral_v1,
)
from src.ops.section_11_13_5_live_canary_minimum_exposure_v1.okx_live_canary_signer_v1 import (
    build_okx_live_canary_auth_headers_v1,
)

HOST = REUSED_BINDING_REST_HOST
BASE = f"https://{HOST}"
INST = "BTC-USD_UM_XPERP-310404"
INST_TYPE = "FUTURES"
INST_FAMILY = "BTC-USD_UM_XPERP"
ULY = "BTC-USD"
TD_MODE = "cross"
VAULT = Path(
    "/Users/frnkhrz/Peak_Trade/.ops_local/section_11_13_5_live_canary_minimum_exposure/secrets/secretref_vault.json"
)
OUT = Path("/tmp/pt_11135_post_k_cross_imr_leverage_get_snapshot.json")

FORBIDDEN_PATH_MARKERS = (
    "/trade/order",
    "/trade/cancel-order",
    "/asset/transfer",
    "/asset/withdrawal",
    "/account/set-",
    "withdraw",
)
GET_COUNT = 0


def _assert_get_path(path: str) -> None:
    if not path.startswith("/api/v5/"):
        raise RuntimeError(f"PATH_NOT_API_V5:{path}")
    path_only = path.split("?", 1)[0].lower()
    joined = path.lower()
    for marker in FORBIDDEN_PATH_MARKERS:
        if marker in path_only or marker in joined:
            raise RuntimeError(f"MUTATION_PATH_BLOCKED:{path}")
    if "set-leverage" in joined:
        raise RuntimeError(f"SET_LEVERAGE_BLOCKED:{path}")


def _get(path: str, headers: dict[str, str] | None = None) -> dict[str, Any]:
    global GET_COUNT
    _assert_get_path(path)
    url = f"{BASE}{path}"
    hdrs = {"User-Agent": USER_AGENT_CANARY, "Accept": "application/json"}
    if headers:
        # Do not copy secrets into logs; headers used only for the request.
        hdrs.update(headers)
    req = Request(url, method="GET", headers=hdrs)
    if str(req.get_method() or "").upper() != "GET":
        raise RuntimeError("NON_GET_HARD_BLOCK")
    ctx = ssl.create_default_context()
    GET_COUNT += 1
    try:
        with urlopen(req, timeout=15, context=ctx) as resp:  # noqa: S310
            status = int(getattr(resp, "status", 200))
            body = resp.read()
    except HTTPError as exc:
        status = int(exc.code)
        body = exc.read() if hasattr(exc, "read") else b""
    except URLError as exc:
        return {
            "http_status": None,
            "error": type(exc).__name__,
            "error_reason": str(exc.reason) if getattr(exc, "reason", None) else str(exc),
            "path": path,
            "payload": None,
        }
    try:
        payload = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        payload = {"_unparsed": True, "byte_len": len(body)}
    if not isinstance(payload, dict):
        payload = {"_non_object": True, "type": type(payload).__name__}
    return {"http_status": status, "path": path, "payload": payload}


def _signed_get(path: str, handle: Any) -> dict[str, Any]:
    url = f"{BASE}{path}"
    headers = build_okx_live_canary_auth_headers_v1(handle=handle, url=url, method="GET")
    # Strip any simulation header if a future signer regression added one.
    for k in list(headers):
        if "simul" in k.lower():
            raise RuntimeError(f"DEMO_SIMULATION_HEADER_FORBIDDEN:{k}")
    return _get(path, headers=headers)


def _payload(resp: dict[str, Any]) -> dict[str, Any]:
    p = resp.get("payload")
    return p if isinstance(p, dict) else {}


def _rows(resp: dict[str, Any]) -> list[dict[str, Any]]:
    data = _payload(resp).get("data")
    if isinstance(data, list):
        return [r for r in data if isinstance(r, dict)]
    return []


def _first(resp: dict[str, Any]) -> dict[str, Any] | None:
    rows = _rows(resp)
    return rows[0] if rows else None


def _pick(row: dict[str, Any] | None, *keys: str) -> dict[str, Any]:
    if not row:
        return {k: None for k in keys}
    return {k: row.get(k) for k in keys}


def _dec(value: Any) -> Decimal | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    try:
        return Decimal(text)
    except (InvalidOperation, ValueError):
        return None


def _meta(resp: dict[str, Any]) -> dict[str, Any]:
    payload = _payload(resp)
    return {
        "http_status": resp.get("http_status"),
        "okx_code": payload.get("code"),
        "okx_msg": payload.get("msg"),
        "path": resp.get("path"),
        "error": resp.get("error"),
        "row_count": len(_rows(resp)),
    }


def main() -> int:
    public_inst = _get(f"/api/v5/public/instruments?instType={INST_TYPE}&instId={INST}")
    ticker = _get(f"/api/v5/market/ticker?instId={INST}")
    mark = _get(f"/api/v5/public/mark-price?instType={INST_TYPE}&instId={INST}")
    pub_tiers = _get(
        f"/api/v5/public/position-tiers?instType={INST_TYPE}&tdMode={TD_MODE}"
        f"&instFamily={INST_FAMILY}&instId={INST}"
    )
    if _payload(pub_tiers).get("code") not in {None, "0"} or not _rows(pub_tiers):
        pub_tiers_family = _get(
            f"/api/v5/public/position-tiers?instType={INST_TYPE}&tdMode={TD_MODE}"
            f"&instFamily={INST_FAMILY}"
        )
    else:
        pub_tiers_family = None

    backend = build_file_secretref_vault_backend_v1(vault_file=VAULT)
    handle = resolve_and_load_live_canary_secretref_ephemeral_v1(
        secret_reference=REQUIRED_SECRETREF_URI,
        vault_backend=backend,
        credential_class=REQUIRED_CREDENTIAL_CLASS,
    )
    private: dict[str, Any] = {}
    try:
        private["config"] = _signed_get("/api/v5/account/config")
        private["balance"] = _signed_get("/api/v5/account/balance")
        private["positions"] = _signed_get("/api/v5/account/positions")
        private["pending"] = _signed_get("/api/v5/trade/orders-pending")
        private["acct_inst"] = _signed_get(
            f"/api/v5/account/instruments?instType={INST_TYPE}&instId={INST}"
        )
        private["acct_inst"]["NOT_ON_SUBMIT_PATH"] = True
        private["leverage_info"] = _signed_get(
            f"/api/v5/account/leverage-info?instId={INST}&mgnMode={TD_MODE}"
        )
        private["trade_fee"] = _signed_get(
            f"/api/v5/account/trade-fee?instType={INST_TYPE}&instId={INST}"
        )
        if _payload(private["trade_fee"]).get("code") not in {None, "0"} or not _rows(
            private["trade_fee"]
        ):
            private["trade_fee_family"] = _signed_get(
                f"/api/v5/account/trade-fee?instType={INST_TYPE}&instFamily={INST_FAMILY}"
            )
    finally:
        release_live_canary_ephemeral_material_v1(handle)

    inst_row = _first(public_inst)
    tick_row = _first(ticker)
    mark_row = _first(mark)
    cfg_row = _first(private["config"])
    bal_row = _first(private["balance"])
    acct_inst_rows = _rows(private["acct_inst"])
    acct_inst_row = next((r for r in acct_inst_rows if r.get("instId") == INST), None)
    if acct_inst_row is None and acct_inst_rows:
        acct_inst_row = acct_inst_rows[0]

    pos_rows = _rows(private["positions"])
    inst_pos = [r for r in pos_rows if r.get("instId") == INST]
    pending_rows = _rows(private["pending"])
    lev_rows = _rows(private["leverage_info"])
    lev_inst_rows = [r for r in lev_rows if str(r.get("instId") or "") == INST]
    if not lev_inst_rows:
        lev_inst_rows = lev_rows

    details = []
    if isinstance(bal_row, dict) and isinstance(bal_row.get("details"), list):
        for d in bal_row["details"]:
            if not isinstance(d, dict):
                continue
            details.append(
                {
                    "ccy": d.get("ccy"),
                    "eq": d.get("eq"),
                    "availEq": d.get("availEq"),
                    "availBal": d.get("availBal"),
                    "cashBal": d.get("cashBal"),
                    "frozenBal": d.get("frozenBal"),
                    "upl": d.get("upl"),
                    "imr": d.get("imr"),
                    "mmr": d.get("mmr"),
                }
            )

    pos_lev_fields = []
    for r in inst_pos:
        pos_lev_fields.append(
            _pick(
                r,
                "instId",
                "mgnMode",
                "pos",
                "posSide",
                "lever",
                "imr",
                "mmr",
                "mgnRatio",
                "notionalUsd",
                "margin",
                "ccy",
            )
        )

    tier_source = pub_tiers
    tier_source_name = "public_position_tiers_instId_family"
    if pub_tiers_family is not None:
        if _rows(pub_tiers_family) and not _rows(pub_tiers):
            tier_source = pub_tiers_family
            tier_source_name = "public_position_tiers_family_fallback"
    tier_rows_raw = _rows(tier_source)
    tier_rows = []
    qty_one_tier = None
    for r in tier_rows_raw:
        compact = _pick(
            r,
            "instId",
            "instFamily",
            "uly",
            "tier",
            "minSz",
            "maxSz",
            "imr",
            "mmr",
            "maxLever",
            "posType",
            "tdMode",
        )
        # Preserve extra leverage-related keys if present.
        for extra in ("lever", "optMgnFactor", "quoteMaxAmt", "baseMaxAmt"):
            if extra in r:
                compact[extra] = r.get(extra)
        tier_rows.append(compact)
        min_sz = _dec(r.get("minSz"))
        max_sz = _dec(r.get("maxSz"))
        if min_sz is None or max_sz is None:
            continue
        if min_sz <= Decimal("1") <= max_sz:
            qty_one_tier = compact

    fee_resp = private.get("trade_fee_family") or private["trade_fee"]
    fee_row = _first(fee_resp)
    fee_pick = _pick(
        fee_row,
        "instType",
        "level",
        "taker",
        "maker",
        "takerU",
        "makerU",
        "takerUSDC",
        "makerUSDC",
        "ruleType",
        "delivery",
        "exercise",
        "category",
    )

    mark_px = None
    last_px = None
    if mark_row:
        mark_px = mark_row.get("markPx")
    if tick_row:
        last_px = tick_row.get("last")
        if mark_px in {None, ""}:
            mark_px = tick_row.get("markPx")

    price_type = None
    price_ref = None
    if _dec(mark_px) is not None and _dec(mark_px) > 0:
        price_type = "markPx"
        price_ref = str(mark_px)
    elif _dec(last_px) is not None and _dec(last_px) > 0:
        price_type = "last"
        price_ref = str(last_px)

    ct_val = None
    if inst_row and inst_row.get("ctVal"):
        ct_val = str(inst_row.get("ctVal"))
    elif acct_inst_row and acct_inst_row.get("ctVal"):
        ct_val = str(acct_inst_row.get("ctVal"))

    notional = None
    if price_ref is not None and ct_val is not None:
        p = _dec(price_ref)
        c = _dec(ct_val)
        if p is not None and c is not None:
            notional = str(p * c * Decimal("1"))

    snapshot = {
        "DOCUMENT_CLASS": "SECTION_11_13_5_POST_K_CROSS_IMR_LEVERAGE_EVIDENCE_GET_ONLY",
        "DOCUMENT_ROLE": "GET_ONLY_FORENSIC_EVIDENCE_NON_SSOT",
        "METHOD": "GET",
        "POST_COUNT": 0,
        "HOST": HOST,
        "EXPECTED_UID": REUSED_BINDING_ACCOUNT_SCOPE,
        "CANARY_INSTRUMENT": INST,
        "CANARY_INST_TYPE": INST_TYPE,
        "PRODUCT_RULE_TYPE": "xperp",
        "SETTLEMENT_ACCOUNT_TRUTH": "USDC",
        "TDMODE_TARGET": TD_MODE,
        "GET_REQUEST_COUNT": GET_COUNT,
        "public_instruments": {
            **_meta(public_inst),
            **_pick(
                inst_row,
                "instId",
                "instType",
                "ruleType",
                "state",
                "minSz",
                "lotSz",
                "tickSz",
                "ctVal",
                "ctValCcy",
                "settleCcy",
                "lever",
                "uly",
                "instFamily",
            ),
            "lever_classification": "MAX_ALLOWED_LEVERAGE_OR_INSTRUMENT_LIMIT_NOT_SET_ACCOUNT_LEVERAGE",
        },
        "ticker": {
            **_meta(ticker),
            **_pick(tick_row, "instId", "last", "markPx", "askPx", "bidPx"),
        },
        "mark_price": {
            **_meta(mark),
            **_pick(mark_row, "instId", "instType", "markPx", "ts"),
        },
        "public_position_tiers": {
            **_meta(tier_source),
            "source_variant": tier_source_name,
            "fallback_family_meta": _meta(pub_tiers_family) if pub_tiers_family else None,
            "qty_one_tier": qty_one_tier,
            "tiers": tier_rows[:12],
            "tier_count_total": len(tier_rows),
            "classification": "PUBLIC_TIER_LIMIT_NOT_SET_ACCOUNT_LEVERAGE",
        },
        "account_config": {
            **_meta(private["config"]),
            **_pick(cfg_row, "uid", "acctLv", "posMode", "perm", "level", "roleType", "spotOffsetType", "autoLoan"),
        },
        "account_balance": {
            **_meta(private["balance"]),
            **_pick(
                bal_row,
                "totalEq",
                "isoEq",
                "adjEq",
                "ordFroz",
                "imr",
                "mmr",
                "mgnRatio",
                "notionalUsd",
                "upl",
            ),
            "details": details,
        },
        "positions": {
            **_meta(private["positions"]),
            "instrument_rows": len(inst_pos),
            "position_size": (str(inst_pos[0].get("pos")) if inst_pos else "0"),
            "leverage_related_fields": pos_lev_fields,
        },
        "orders_pending": {
            **_meta(private["pending"]),
            "count": len(pending_rows),
        },
        "account_instruments_diagnostic": {
            **_meta(private["acct_inst"]),
            "NOT_ON_SUBMIT_PATH": True,
            "CAUSAL_RELATION_TO_SUBMIT": "NONE",
            **_pick(
                acct_inst_row,
                "instId",
                "instType",
                "ruleType",
                "state",
                "minSz",
                "lotSz",
                "tickSz",
                "ctVal",
                "ctValCcy",
                "settleCcy",
                "lever",
            ),
            "lever_classification": "UNKNOWN_NOT_AUTOMATICALLY_SET_ACCOUNT_LEVERAGE",
        },
        "account_leverage_info": {
            **_meta(private["leverage_info"]),
            "request_params": {"instId": INST, "mgnMode": TD_MODE},
            "rows": [
                _pick(r, "instId", "mgnMode", "posSide", "lever", "ccy")
                for r in lev_inst_rows
            ],
            "classification_if_lever_present": "SET_ACCOUNT_LEVERAGE",
        },
        "account_trade_fee": {
            **_meta(fee_resp),
            **fee_pick,
        },
        "derived": {
            "PRICE_REFERENCE_TYPE": price_type,
            "PRICE_REFERENCE": price_ref,
            "CTVAL": ct_val,
            "MINIMUM_CONTRACT_SIZE": "1",
            "MINIMUM_NOTIONAL_ESTIMATE": notional,
            "UID_MATCH": bool(
                cfg_row and str(cfg_row.get("uid") or "") == REUSED_BINDING_ACCOUNT_SCOPE
            ),
            "POS_MODE": (cfg_row or {}).get("posMode") if cfg_row else None,
            "ACCOUNT_LEVEL": (cfg_row or {}).get("acctLv") if cfg_row else None,
        },
    }
    OUT.write_text(json.dumps(snapshot, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")
    print(json.dumps(snapshot, indent=2, ensure_ascii=True))
    print(f"GET_REQUEST_COUNT={GET_COUNT}", flush=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

